/**
 * The app's core. The Swift app opens one per process and shares it.
 */
public protocol SketchbookCoreProtocol: AnyObject, Sendable {
    
    /**
     * Adds an empty layer on top, named "Layer N" when `name` is `None`.
     */
    func addLayer(sketchId: UInt64, name: String?) async throws  -> SketchDetail
    
    /**
     * The host's background time ran out: finishing work stops.
     */
    func backgroundTimeExpired() 
    
    /**
     * Whether commands or finishing work are still running; the
     * host holds background time while they are.
     */
    func backgroundWorkPending()  -> Bool
    
    /**
     * Empties a layer. One undo step.
     */
    func clearLayer(sketchId: UInt64, layerId: UInt64) async throws  -> SketchDetail
    
    /**
     * A new sketch with one empty layer.
     */
    func createSketch(title: String, paper: Paper) async throws  -> SketchDetail
    
    func deleteLayer(sketchId: UInt64, layerId: UInt64) async throws  -> SketchDetail
    
    /**
     * Deletes a sketch, its history and the drawings only it used.
     */
    func deleteSketch(id: UInt64) async throws 
    
    /**
     * A layer's new drawing, after a stroke ended (or an erase, or a
     * lasso move). One undo step. The same drawing twice changes nothing.
     */
    func draw(sketchId: UInt64, layerId: UInt64, drawing: Data) async throws  -> SketchDetail
    
    /**
     * Puts a copy of a layer just above it.
     */
    func duplicateLayer(sketchId: UInt64, layerId: UInt64) async throws  -> SketchDetail
    
    /**
     * A copy of a sketch, called "… Copy". Its undo history starts empty.
     */
    func duplicateSketch(id: UInt64) async throws  -> SketchDetail
    
    /**
     * The runtime's event stream: `Changed { revision }` after each
     * committed command, phase changes, and drops. Nil after shutdown.
     */
    func events()  -> RuntimeEvents?
    
    /**
     * What to render to export `sketch_ids`, in that order, and where to
     * write it: PNG is a file per sketch, PDF one file with a page per
     * sketch. Hidden and empty layers are left out. Never waits for a
     * command.
     */
    func exportPlan(sketchIds: [UInt64], format: ExportFormat) throws  -> ExportPlan
    
    /**
     * What the runtime found at open (unfinished background work).
     */
    func launchReport()  -> LaunchReport
    
    /**
     * Moves a layer to `to`, counted from the bottom (0).
     */
    func moveLayer(sketchId: UInt64, layerId: UInt64, to: UInt32) async throws  -> SketchDetail
    
    /**
     * The phase last reported.
     */
    func phase()  -> AppPhase
    
    func redo(sketchId: UInt64) async throws  -> SketchDetail
    
    func renameLayer(sketchId: UInt64, layerId: UInt64, name: String) async throws  -> SketchDetail
    
    func renameSketch(id: UInt64, title: String) async throws 
    
    /**
     * The last committed revision.
     */
    func revision()  -> UInt64
    
    /**
     * From 0 to 1. Call it as a slider moves: changes to one layer less
     * than two seconds apart are one undo step.
     */
    func setLayerOpacity(sketchId: UInt64, layerId: UInt64, opacity: Double) async throws  -> SketchDetail
    
    func setLayerVisible(sketchId: UInt64, layerId: UInt64, visible: Bool) async throws  -> SketchDetail
    
    func setPaper(sketchId: UInt64, paper: Paper) async throws  -> SketchDetail
    
    /**
     * The host reports the application lifecycle phase.
     */
    func setPhase(phase: AppPhase) 
    
    /**
     * The list's picture of a sketch: a PNG the app rendered after a
     * change. Not an undo step.
     */
    func setThumbnail(sketchId: UInt64, png: Data) async throws 
    
    /**
     * Refuses new commands, stops work in flight and ends event
     * streams. Commands already accepted still finish and save.
     */
    func shutdown() 
    
    /**
     * A sketch with its layers and what undo and redo would do. Never
     * waits for a command.
     */
    func sketch(id: UInt64) throws  -> SketchDetail
    
    /**
     * Every sketch, most recently changed first. Never waits for a command.
     */
    func sketches()  -> [SketchSummary]
    
    func undo(sketchId: UInt64) async throws  -> SketchDetail
    
}
