public struct FfiConverterTypeSketchbookCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = SketchbookCore

    public static func lift(_ handle: UInt64) throws -> SketchbookCore {
        return SketchbookCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: SketchbookCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SketchbookCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: SketchbookCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


