/**
 * Everything that can go wrong, in the app's words. `sketchbook_error_kind`
 * maps each case to the framework's [`ErrorKind`].
 */
public 
enum SketchbookError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case EmptyName
    case NameTooLong(max: UInt32
    )
    case NotFound(id: UInt64
    )
    case TooManyLayers(max: UInt32
    )
    case LastLayer
    case BadOpacity
    case NothingToUndo
    case NothingToRedo
    case NothingToExport
    case Drawing(reason: String
    )
    case InUse
    case Corrupt(reason: String
    )
    case NewerData
    case Storage(reason: String
    )
    /**
     * Stopped by the runtime: cancelled, interrupted by the background,
     * or shut down. `kind` says which.
     */
    case Stopped(kind: ErrorKind
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension SketchbookError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSketchbookError: FfiConverterRustBuffer {
    typealias SwiftType = SketchbookError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SketchbookError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .EmptyName
        case 2: return .NameTooLong(
            max: try FfiConverterUInt32.read(from: &buf)
            )
        case 3: return .NotFound(
            id: try FfiConverterUInt64.read(from: &buf)
            )
        case 4: return .TooManyLayers(
            max: try FfiConverterUInt32.read(from: &buf)
            )
        case 5: return .LastLayer
        case 6: return .BadOpacity
        case 7: return .NothingToUndo
        case 8: return .NothingToRedo
        case 9: return .NothingToExport
        case 10: return .Drawing(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 11: return .InUse
        case 12: return .Corrupt(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 13: return .NewerData
        case 14: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 15: return .Stopped(
            kind: try FfiConverterTypeErrorKind.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SketchbookError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .EmptyName:
            writeInt(&buf, Int32(1))
        
        
        case let .NameTooLong(max):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(max, into: &buf)
            
        
        case let .NotFound(id):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(id, into: &buf)
            
        
        case let .TooManyLayers(max):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(max, into: &buf)
            
        
        case .LastLayer:
            writeInt(&buf, Int32(5))
        
        
        case .BadOpacity:
            writeInt(&buf, Int32(6))
        
        
        case .NothingToUndo:
            writeInt(&buf, Int32(7))
        
        
        case .NothingToRedo:
            writeInt(&buf, Int32(8))
        
        
        case .NothingToExport:
            writeInt(&buf, Int32(9))
        
        
        case let .Drawing(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .InUse:
            writeInt(&buf, Int32(11))
        
        
        case let .Corrupt(reason):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NewerData:
            writeInt(&buf, Int32(13))
        
        
        case let .Storage(reason):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Stopped(kind):
            writeInt(&buf, Int32(15))
            FfiConverterTypeErrorKind.write(kind, into: &buf)
            
        }
    }
}


